data.minimal_example:
LinkedInUserWidget(
   redirectUrl: redirectUrl,
   clientId: clientId,
   clientSecret: clientSecret,
   onGetUserProfile:
       (UserSucceededAction linkedInUser) {
            print('Access token ${linkedInUser.user.token}');
   },
   onError: (UserFailedAction e) {
            print('Error: ${e.toString()}');
   },
)
